});
/* '+' along the inner cylinder */
for (let i = 0; i < 6; i++) {
  const x = -3.2 + i * 1.5;
  glyph(TEX_PLUS, x, 0.36, 0.99, 0.34);
  glyph(TEX_PLUS, x, -0.36, 0.99, 0.34);
}
/* '−' along the outer shell (top + bottom rows) */
for (let i = 0; i < 7; i++) {
  const x = -3.6 + i * 1.35;
  glyph(TEX_MINUS, x, 3.02 * Math.sin(1.02), 3.02 * Math.cos(1.02), 0.4);
  glyph(TEX_MINUS, x, -3.02 * Math.sin(1.02), 3.02 * Math.cos(1.02), 0.4);
}
/* '−' around the near rim */
for (let i = 0; i < 14; i++) {
  const a = i / 14 * Math.PI * 2 + 0.12;
  glyph(TEX_MINUS, XN - 0.09, 2.86 * Math.sin(a), 2.86 * Math.cos(a), 0.36);
}

/* ── red E arrows in the near-end plane ─────────────────────────────────── */
const fieldGroup = new THREE.Group(); scene.add(fieldGroup);
for (let i = 0; i < 12; i++) {
