   outer shell            → CylinderGeometry(3,3,10, open) rotated to +X, MeshPhysicalMaterial #C6CBE0 opacity .45
   top highlight band     → partial CylinderGeometry (theta band) #E8EAF3
   near annular face      → RingGeometry(2.72,3.0) facing -X at x=-5, #9AA1BF
   far end cap disc       → CircleGeometry(3) facing +X at x=+5, #D9DCEA
   far faint circles      → LineLoop r=1, 2.85, 3  #B9BFD6
   inner conductor        → CylinderGeometry(1,1,10, capped) #AFB5D0
   inner near face        → CircleGeometry(1) #F2F3F8 at x=-4.99
   '+' glyphs             → Sprite(canvas '+') navy #2B2F4A : 17 on near face, 12 along length
   '−' glyphs             → Sprite(canvas '−') navy : 7 top + 7 bottom + 14 on near rim
   E arrows (near plane)  → 12 × ArrowHelper, r=R1→2.8, #E03A2F
   E arrows (at surface)  → 8 × ArrowHelper at x=0, tail on dashed cyl, length ∝ 1/r
   Gaussian surface       → 2 dashed ellipses + 2 dashed generatrices, LineDashedMaterial #F0A030
   Gaussian tint shell    → open CylinderGeometry, MeshBasicMaterial green/grey opacity .13
   leader                 → CatmullRomCurve3 black Line + ConeGeometry arrowhead
   far radius arrows      → 3 × ArrowHelper black from (5,0,0): R1, r, R2
   axis                   → dashed grey Line x=-5.6…5.6
─────────────────────────────────────────────────────────────────────────── */

const R1 = 1.0, R2 = 3.0, LEN = 10, XN = -5, XF = 5;
const NAVY = 0x2B2F4A, RED = 0xE03A2F, ORANGE = 0xF0A030;

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.85));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.5); keyLight.position.set(-6, 8, 9); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.22); fillLight.position.set(6, -5, -7); scene.add(fillLight);

function cylX(r, len, seg, open, thetaStart, thetaLength) {
  const g = new THREE.CylinderGeometry(r, r, len, seg, 1, !!open,
    thetaStart === undefined ? 0 : thetaStart,
    thetaLength === undefined ? Math.PI * 2 : thetaLength);
  g.rotateZ(-Math.PI / 2);               // +Y → +X
  return g;
}

/* ── outer conducting shell ─────────────────────────────────────────────── */
const shellMat = new THREE.MeshPhysicalMaterial({
  color: 0xC6CBE0, transparent: true, opacity: 0.45, depthWrite: false,
  side: THREE.DoubleSide, roughness: 0.35, metalness: 0.04, clearcoat: 0.4
});
const shell = new THREE.Mesh(cylX(R2, LEN, 72, true), shellMat);
scene.add(shell);
registerInteractive(shell, {
  title: 'Outer shell (−Q)', tooltip: 'Outer conductor, radius R₂ = 3',
  body: 'The outer coaxial conductor of radius R₂ carries charge −Q on its inner wall. Outside it the enclosed charge is +Q − Q = 0, so the field vanishes.'
});

const band = new THREE.Mesh(
  cylX(R2 * 1.004, LEN, 48, true, -Math.PI / 2 - 0.6, 1.2),
  new THREE.MeshBasicMaterial({ color: 0xE8EAF3, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false })
);
scene.add(band);

/* near annular face (cutaway) */
const ringG = new THREE.RingGeometry(2.72, R2, 72); ringG.rotateY(-Math.PI / 2);
const nearRing = new THREE.Mesh(ringG, new THREE.MeshPhysicalMaterial({
  color: 0x9AA1BF, side: THREE.DoubleSide, roughness: 0.5, metalness: 0.05
}));
nearRing.position.x = XN; scene.add(nearRing);

/* far end cap */
const capG = new THREE.CircleGeometry(R2, 72); capG.rotateY(Math.PI / 2);
const farCap = new THREE.Mesh(capG, new THREE.MeshPhysicalMaterial({
  color: 0xD9DCEA, side: THREE.DoubleSide, transparent: true, opacity: 0.9, roughness: 0.6
}));
farCap.position.x = XF; scene.add(farCap);

/* faint concentric circles on the far cap */
function circleLoop(x, r, color) {
  const pts = [];
  for (let i = 0; i <= 96; i++) { const a = i / 96 * Math.PI * 2; pts.push(new THREE.Vector3(x, r * Math.sin(a), r * Math.cos(a))); }
  const l = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color }));
  scene.add(l); return l;
}
circleLoop(XF - 0.02, R1, 0xB0B6D0);
circleLoop(XF - 0.02, 2.85, 0xB0B6D0);
circleLoop(XF - 0.02, R2, 0x9AA1BF);
circleLoop(XN - 0.01, R2, 0x8C93B5);

/* ── inner conductor ────────────────────────────────────────────────────── */
const inner = new THREE.Mesh(cylX(R1, LEN, 56, false), new THREE.MeshPhysicalMaterial({
  color: 0xAFB5D0, roughness: 0.4, metalness: 0.08, transparent: true, opacity: 0.96
}));
scene.add(inner);
registerInteractive(inner, {
  title: 'Inner conductor (+Q)', tooltip: 'Inner cylinder, radius R₁ = 1',
  body: 'The inner cylinder of radius R₁ carries +Q, i.e. a linear charge density λ = Q/L on its surface. Inside the metal itself the field is zero.'
});

const innerFaceG = new THREE.CircleGeometry(R1, 56); innerFaceG.rotateY(-Math.PI / 2);
const innerFace = new THREE.Mesh(innerFaceG, new THREE.MeshBasicMaterial({ color: 0xF2F3F8, side: THREE.DoubleSide }));
innerFace.position.x = XN - 0.005; scene.add(innerFace);

/* ── axis line ──────────────────────────────────────────────────────────── */
{
  const axis = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-5.7, 0, 0), new THREE.Vector3(5.7, 0, 0)]),
    new THREE.LineDashedMaterial({ color: 0x777C93, dashSize: 0.22, gapSize: 0.16 }));
  axis.computeLineDistances(); scene.add(axis);
}

/* ── charge glyph sprites ───────────────────────────────────────────────── */
function glyphTex(ch) {
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = '#2B2F4A'; g.font = 'bold 58px sans-serif';
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(ch, 32, 34);
  const t = new THREE.CanvasTexture(c); t.needsUpdate = true; return t;
}
const TEX_PLUS = glyphTex('+'), TEX_MINUS = glyphTex('\u2212');
const signsGroup = new THREE.Group(); scene.add(signsGroup);
function glyph(tex, x, y, z, s) {
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  sp.position.set(x, y, z); sp.scale.set(s, s, 1); signsGroup.add(sp); return sp;
}
/* '+' crowded on the inner near face */
glyph(TEX_PLUS, XN - 0.07, 0, 0, 0.3);
[[0.42, 6, 0], [0.78, 10, 0.3]].forEach(([rr, n, ph]) => {
  for (let i = 0; i < n; i++) {
    const a = ph + i / n * Math.PI * 2;
    glyph(TEX_PLUS, XN - 0.07, rr * Math.sin(a), rr * Math.cos(a), 0.3);
  }
});
/* '+' along the inner cylinder */
for (let i = 0; i < 6; i++) {
  const x = -3.2 + i * 1.5;
  glyph(TEX_PLUS, x, 0.36, 0.99, 0.34);
  glyph(TEX_PLUS, x, -0.36, 0.99, 0.34);
}
/* '−' along the outer shell (top + bottom rows) */
for (let i = 0; i < 7; i++) {
  const x = -3.6 + i * 1.35;
  glyph(TEX_MINUS, x, 3.02 * Math.sin(1.02), 3.02 * Math.cos(1.02), 0.4);
  glyph(TEX_MINUS, x, -3.02 * Math.sin(1.02), 3.02 * Math.cos(1.02), 0.4);
}
/* '−' around the near rim */
for (let i = 0; i < 14; i++) {
  const a = i / 14 * Math.PI * 2 + 0.12;
  glyph(TEX_MINUS, XN - 0.09, 2.86 * Math.sin(a), 2.86 * Math.cos(a), 0.36);
}

/* ── red E arrows in the near-end plane ─────────────────────────────────── */
const fieldGroup = new THREE.Group(); scene.add(fieldGroup);
for (let i = 0; i < 12; i++) {
  const a = i / 12 * Math.PI * 2;
  const dir = new THREE.Vector3(0, Math.sin(a), Math.cos(a));
  const org = dir.clone().multiplyScalar(R1).setX(XN + 0.16);
  fieldGroup.add(new THREE.ArrowHelper(dir, org, 1.78, RED, 0.34, 0.2));
}

/* ── E arrows sitting ON the Gaussian surface (mid-length) ──────────────── */
const surfArrows = [];
for (let i = 0; i < 8; i++) {
  const a = i / 8 * Math.PI * 2 + 0.2;
  const arw = new THREE.ArrowHelper(new THREE.Vector3(0, Math.sin(a), Math.cos(a)), new THREE.Vector3(0, 0, 0), 1, RED, 0.22, 0.14);
  arw.userData.ang = a;
  fieldGroup.add(arw); surfArrows.push(arw);
}

/* ── Gaussian surface: dashed lines + tint shell ────────────────────────── */
const dashMat = new THREE.LineDashedMaterial({ color: ORANGE, dashSize: 0.25, gapSize: 0.18, depthTest: false });
function mkLine(pts) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), dashMat);
  l.computeLineDistances(); l.renderOrder = 6; scene.add(l); return l;
}
function setLine(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  line.computeLineDistances();
}
function ellipsePts(x, r) {
  const p = []; for (let i = 0; i <= 128; i++) { const a = i / 128 * Math.PI * 2; p.push(new THREE.Vector3(x, r * Math.sin(a), r * Math.cos(a))); }
  return p;
}
const gNear = mkLine(ellipsePts(XN - 0.03, 2));
const gFar = mkLine(ellipsePts(XF - 0.06, 2));
const gTop = mkLine([new THREE.Vector3(XN - 0.03, 2, 0), new THREE.Vector3(XF - 0.06, 2, 0)]);
const gBot = mkLine([new THREE.Vector3(XN - 0.03, -2, 0), new THREE.Vector3(XF - 0.06, -2, 0)]);

const gaussShell = new THREE.Mesh(cylX(1, LEN - 0.1, 56, true), new THREE.MeshBasicMaterial({
  color: 0x2E9E5B, transparent: true, opacity: 0.13, side: THREE.DoubleSide, depthWrite: false
}));
gaussShell.scale.set(1, 2, 2); scene.add(gaussShell);
registerInteractive(gaussShell, {
  title: 'Gaussian surface', tooltip: 'Coaxial cylinder of radius r',
  body: 'A closed coaxial cylinder of radius r and length L. By symmetry E is radial and constant on its curved wall, so Φ = E·(2πrL) = Q_enc/ε₀ ⇒ E = λ/(2πε₀r) whenever R₁ < r < R₂.'
});

/* ── leader + 'Gaussian surface' callout ────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x111111 });
const leader = new THREE.Line(new THREE.BufferGeometry(), leaderMat);
leader.renderOrder = 7; scene.add(leader);
const leaderHead = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.3, 14),
  new THREE.MeshBasicMaterial({ color: 0x111111 }));
scene.add(leaderHead);

function updateLeader(r) {
  const end = new THREE.Vector3(0.5, r + 0.06, 0);
  const pts = [
    new THREE.Vector3(3.05, 4.15, 0),
    new THREE.Vector3(2.35, 4.05, 0),
    new THREE.Vector3(1.75, 3.55, 0),
    new THREE.Vector3(1.95, 3.95, 0),
    new THREE.Vector3(1.35, 3.85, 0),
    new THREE.Vector3(0.85, r + 0.85, 0),
    end.clone()
  ];
  const curve = new THREE.CatmullRomCurve3(pts);
  const cp = curve.getPoints(90);
  leader.geometry.dispose();
  leader.geometry = new THREE.BufferGeometry().setFromPoints(cp);
  const dir = cp[cp.length - 1].clone().sub(cp[cp.length - 6]).normalize();
  leaderHead.position.copy(end).addScaledVector(dir, -0.1);
  leaderHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
}
updateLeader(2);

/* ── far-end radius arrows ──────────────────────────────────────────────── */
const farOrigin = new THREE.Vector3(XF - 0.1, 0, 0);
const dirR1 = new THREE.Vector3(0, 1, 0.12).normalize();
const dirRr = new THREE.Vector3(0, 0.707, 0.707).normalize();
const dirR2 = new THREE.Vector3(0, -0.5, 0.866).normalize();
const arrR1 = new THREE.ArrowHelper(dirR1, farOrigin, R1, 0x111111, 0.22, 0.13);
const arrRr = new THREE.ArrowHelper(dirRr, farOrigin, 2, 0x111111, 0.22, 0.13);
const arrR2 = new THREE.ArrowHelper(dirR2, farOrigin, R2, 0x111111, 0.24, 0.14);
scene.add(arrR1, arrRr, arrR2);
const axisDot = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 10), new THREE.MeshBasicMaterial({ color: 0x111111 }));
axisDot.position.copy(farOrigin); scene.add(axisDot);

/* ── camera (after all geometry) ────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 155, elevationDeg: 12, rollDeg: 0, heightFraction: 0.6 });

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<i>E</i>', new THREE.Vector3(XN + 0.1, 2.45, 0.25), { fontSize: '15px', bold: true, offset: [-16, -8] });
addLabel('Gaussian surface', new THREE.Vector3(3.05, 4.15, 0), { fontSize: '14px', offset: [58, -12] });
const labR1 = addLabel('<i>R</i><sub>1</sub>', new THREE.Vector3(XF - 0.1, 0.9, 0.11), { fontSize: '15px', offset: [-20, -4] });
const labRr = addLabel('<i>r</i>', new THREE.Vector3(XF - 0.1, 0.7, 0.7), { fontSize: '15px', offset: [-16, 6] });
const labR2 = addLabel('<i>R</i><sub>2</sub>', new THREE.Vector3(XF - 0.1, -0.85, 1.47), { fontSize: '15px', offset: [-18, -10] });

/* ── controls & state ───────────────────────────────────────────────────── */
const el = (id) => document.getElementById(id);
const slider = el('gaussianRadius');
const rVal = el('rVal');
const readout = el('readout');
const chkSigns = el('chkSigns'), chkField = el('chkField'), chkShell = el('chkShell');

const REGIONS = {
  inside: { min: 0.3, max: 0.95, btn: 'regInside' },
  gap: { min: 1.0, max: 3.0, btn: 'regGap' },
  outside: { min: 3.05, max: 3.8, btn: 'regOutside' }
};
let region = 'gap';
let currentR = 2;

function applyR(r) {
  currentR = r;
  rVal.textContent = r.toFixed(2);
  if (Math.abs(parseFloat(slider.value) - r) > 1e-6) slider.value = r;

  setLine(gNear, ellipsePts(XN - 0.03, r));
  setLine(gFar, ellipsePts(XF - 0.06, r));
  setLine(gTop, [new THREE.Vector3(XN - 0.03, r, 0), new THREE.Vector3(XF - 0.06, r, 0)]);
  setLine(gBot, [new THREE.Vector3(XN - 0.03, -r, 0), new THREE.Vector3(XF - 0.06, -r, 0)]);
  gaussShell.scale.set(1, r, r);
  updateLeader(r);

  arrRr.setLength(r, 0.22, 0.13);
  labRr.pos.set(XF - 0.1, 0.45 * r * dirRr.y * 1.4, 0.45 * r * dirRr.z * 1.4);

  const inGap = region === 'gap';
  const len = Math.max(0.28, Math.min(1.7, 1.8 / r));
  surfArrows.forEach(a => {
    const ang = a.userData.ang;
    const dir = new THREE.Vector3(0, Math.sin(ang), Math.cos(ang));
    a.position.copy(dir).multiplyScalar(r);
    a.position.x = 0;
    a.setDirection(dir);
    a.setLength(len, Math.min(0.24, len * 0.4), Math.min(0.15, len * 0.26));
    a.visible = inGap;
  });

  gaussShell.material.color.setHex(inGap ? 0x2E9E5B : 0x8892A6);
  gaussShell.material.opacity = inGap ? 0.14 : 0.10;

  const Erel = inGap ? (1 / r) : 0;
  let qTxt, eTxt;
  if (region === 'inside') {
    qTxt = 'Q<sub>enc</sub> = 0 &nbsp;(surface lies inside the metal)';
    eTxt = '<b>E = 0</b>';
  } else if (region === 'outside') {
    qTxt = 'Q<sub>enc</sub> = +Q − Q = 0';
    eTxt = '<b>E = 0</b> &nbsp;(no field escapes)';
  } else {
    qTxt = 'Q<sub>enc</sub> = +Q = λL &nbsp;(fixed)';
    eTxt = 'E = λ/(2πε₀r) ∝ 1/r = <b>' + Erel.toFixed(3) + '</b> (arb.)';
  }
  readout.innerHTML =
    'r = <b>' + r.toFixed(2) + '</b> &nbsp; (R₁ = 1, R₂ = 3)<br>' +
    qTxt + '<br>' + eTxt +
    '<br><span style="color:#555">C = 2πε₀L / ln(R₂/R₁) = 5.06×10⁻¹⁰ F</span>';

  fieldGroup.visible = chkField.checked;
  fieldGroup.children.forEach(c => { if (!c.userData.ang) c.visible = inGap; });
}

function updateRegionButtons() {
  Object.keys(REGIONS).forEach(k => {
    el(REGIONS[k].btn).classList.toggle('active', k === region);
  });
}

function setRegion(k, value) {
  region = k;
  const R = REGIONS[k];
  slider.min = R.min; slider.max = R.max;
  let v = (value != null) ? value : currentR;
  v = Math.min(R.max, Math.max(R.min, v));
  updateRegionButtons();
  return v;
}

slider.addEventListener('input', () => { cancelTween(); applyR(parseFloat(slider.value)); });
el('regInside').addEventListener('click', () => { cancelTween(); tweenR(setRegion('inside', 0.6)); });
el('regGap').addEventListener('click', () => { cancelTween(); tweenR(setRegion('gap', 2.0)); });
el('regOutside').addEventListener('click', () => { cancelTween(); tweenR(setRegion('outside', 3.4)); });
chkSigns.addEventListener('change', () => { signsGroup.visible = chkSigns.checked; });
chkField.addEventListener('change', () => applyR(currentR));
chkShell.addEventListener('change', () => { shell.visible = band.visible = chkShell.checked; });

/* ── tween ──────────────────────────────────────────────────────────────── */
let tweenId = null;
function cancelTween() { if (tweenId) { cancelAnimationFrame(tweenId); tweenId = null; } }
function tweenR(target) {
  cancelTween();
  const from = currentR, t0 = performance.now(), dur = 700;
  const step = (now) => {
    const u = Math.min(1, (now - t0) / dur);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    applyR(from + (target - from) * e);
    if (u < 1) tweenId = requestAnimationFrame(step); else tweenId = null;
  };
  tweenId = requestAnimationFrame(step);
}

/* ── guided demo ────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The coaxial geometry', r: 2.0, reg: 'gap', n: 'An inner cylinder of radius R₁ carrying +Q sits inside an outer shell of radius R₂ carrying −Q. Red arrows in the gap show the radial field pointing from + to −.' },
  { t: 'Shrink toward R₁', r: 1.1, reg: 'gap', n: 'Move the dashed cylinder close to the inner conductor. The enclosed charge is unchanged, but the area 2πrL is smaller, so E at the surface is large — the arrows lengthen.' },
  { t: 'Expand toward R₂', r: 2.9, reg: 'gap', n: 'Push the dashed cylinder out to just inside the outer shell. Same enclosed +Q, larger area, so E falls off as 1/r and the arrows shorten.' },
  { t: 'Inside the inner conductor', r: 0.5, reg: 'inside', n: 'Choose r < R₁: the Gaussian cylinder encloses no charge, so the flux and the field are zero inside the conductor.' },
  { t: 'Outside the capacitor', r: 3.6, reg: 'outside', n: 'Choose r > R₂: the surface now encloses +Q and −Q together. Net enclosed charge is zero, so no field escapes the capacitor.' }
];
let stepIdx = 0, playTimer = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  el('stepTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + '. ' + s.t;
  el('stepText').textContent = s.n;
  tweenR(setRegion(s.reg, s.r));
}
el('stepNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
el('stepPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
function stopPlay() { if (playTimer) { clearInterval(playTimer); playTimer = null; el('stepPlay').textContent = '▶ Play'; el('stepPlay').classList.remove('active'); } }
el('stepPlay').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  el('stepPlay').textContent = '❚❚ Pause';
  el('stepPlay').classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 4200);
});

/* ── init ───────────────────────────────────────────────────────────────── */
updateRegionButtons();
applyR(2);
goToStep(0);
// @FIGURE_CODE_END

