const gaussShell = new THREE.Mesh(cylX(1, LEN - 0.12, 48, true), new THREE.MeshBasicMaterial({
  color: ORANGE, transparent: true, opacity: 0.06, side: THREE.DoubleSide, depthWrite: false
}));
