registerInteractive(gaussShell, {
  title: 'Gaussian surface', tooltip: 'Coaxial cylinder of radius r',
  body: 'A closed coaxial cylinder of radius r and length L. By symmetry E is radial and constant on its curved wall, so Φ = E·(2πrL) = Q_enc/ε₀ ⇒ E = λ/(2πε₀r) whenever R₁ < r < R₂.'
});

/* ── leader + "Gaussian surface" callout ────────────────────────────────── */
const leaderMat = new THREE.MeshBasicMaterial({ color: 0x111111, depthTest: false, depthWrite: false });
const leader = new THREE.Mesh(new THREE.BufferGeometry(), leaderMat);
leader.renderOrder = 13; scene.add(leader);
const leaderHead = new THREE.Mesh(UNIT_CONE, leaderMat);
leaderHead.renderOrder = 13; leaderHead.scale.set(0.1, 0.3, 0.1); scene.add(leaderHead);
const TEXT_ANCHOR = new THREE.Vector3(2.55, 4.3, 0);

function updateLeader(r) {
  const end = new THREE.Vector3(0.3, r + 0.1, 0);
  const pts = [
    TEXT_ANCHOR.clone(),
    new THREE.Vector3(1.95, 4.24, 0),
    new THREE.Vector3(1.38, 3.82, 0),
    new THREE.Vector3(1.66, 4.2, 0),
    new THREE.Vector3(1.05, 4.06, 0),
    new THREE.Vector3(0.62, r + 0.95, 0),
    end.clone()
