  const curve = new THREE.CatmullRomCurve3(pts);
  const old = leader.geometry;
  leader.geometry = new THREE.TubeGeometry(curve, 80, 0.028, 6, false);
  old?.dispose?.();
  const p = curve.getPoints(80);
  const dir = p[80].clone().sub(p[75]).normalize();
  leaderHead.position.copy(end).addScaledVector(dir, -0.12);
  leaderHead.quaternion.setFromUnitVectors(UP, dir);
