updateLeader(2);

/* ── far-end radius arrows ──────────────────────────────────────────────── */
const farOrigin = new THREE.Vector3(XF - 0.1, 0, 0);
function dirAt(deg) { const t = THREE.MathUtils.degToRad(deg); return new THREE.Vector3(0, Math.cos(t), Math.sin(t)); }
const dirR1 = dirAt(15), dirRr = dirAt(50), dirR2 = dirAt(118);
const arrR1 = makeArrow(0x111111); setArrow(arrR1, farOrigin, dirR1, R1, 0.03, 0.26, 0.095);
const arrRr = makeArrow(0x111111); setArrow(arrRr, farOrigin, dirRr, 2, 0.03, 0.26, 0.095);
const arrR2 = makeArrow(0x111111); setArrow(arrR2, farOrigin, dirR2, R2, 0.03, 0.28, 0.1);
scene.add(arrR1, arrRr, arrR2);
const axisDot = new THREE.Mesh(new THREE.SphereGeometry(0.07, 14, 10),
  new THREE.MeshBasicMaterial({ color: 0x111111, depthTest: false }));
axisDot.renderOrder = 11; axisDot.position.copy(farOrigin); scene.add(axisDot);

/* ── camera (after all geometry) ────────────────────────────────────────── */
setCameraView({
  projection: 'perspective', azimuthDeg: 108, elevationDeg: 11, rollDeg: 0,
  heightFraction: 0.78, target: [0, 0.35, 0]
