/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<i>E</i>', new THREE.Vector3(XN + 0.2, 2.55, 0.3), { fontSize: '20px', bold: true, offset: [-20, -6] });
addLabel('Gaussian surface', TEXT_ANCHOR.clone(), { fontSize: '16px', bold: true, offset: [66, -10] });
const labR1 = addLabel('<i>R</i><sub>1</sub>', farOrigin.clone().addScaledVector(dirR1, 1.06), { fontSize: '19px', offset: [-24, -4] });
const labRr = addLabel('<i>r</i>', farOrigin.clone().addScaledVector(dirRr, 1.3), { fontSize: '19px', offset: [-20, 12] });
const labR2 = addLabel('<i>R</i><sub>2</sub>', farOrigin.clone().addScaledVector(dirR2, 1.9), { fontSize: '19px', offset: [-26, -12] });

/* ── controls & state ───────────────────────────────────────────────────── */
const el = (id) => document.getElementById(id);
const slider = el('gaussianRadius');
const rVal = el('rVal');
const readout = el('readout');
const chkSigns = el('chkSigns'), chkField = el('chkField'), chkShell = el('chkShell');

const REGIONS = {
  inside: { min: 0.3, max: 0.95, btn: 'regInside' },
  gap: { min: 1.0, max: 3.0, btn: 'regGap' },
  outside: { min: 3.05, max: 3.8, btn: 'regOutside' }
};
let region = 'gap';
let currentR = 2;

function applyR(r) {
  currentR = r;
  rVal.textContent = r.toFixed(2);
