  { t: 'The coaxial geometry', r: 2.0, reg: 'gap', n: 'An inner cylinder of radius R₁ carrying +Q sits inside an outer shell of radius R₂ carrying −Q. Red arrows in the gap show the radial field pointing from + to −.' },
  { t: 'Shrink toward R₁', r: 1.1, reg: 'gap', n: 'Move the dashed cylinder close to the inner conductor. The enclosed charge is unchanged, but the area 2πrL is smaller, so E at the surface is large — the arrows lengthen.' },
  { t: 'Expand toward R₂', r: 2.9, reg: 'gap', n: 'Push the dashed cylinder out to just inside the outer shell. Same enclosed +Q, larger area, so E falls off as 1/r and the arrows shorten.' },
  { t: 'Inside the inner conductor', r: 0.5, reg: 'inside', n: 'Choose r < R₁: the Gaussian cylinder encloses no charge, so the flux and the field inside the conductor are zero.' },
