let stepIdx = 0, playTimer = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  el('stepTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + '. ' + s.t;
  el('stepText').textContent = s.n;
  tweenR(setRegion(s.reg, s.r));
}
el('stepNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
el('stepPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
function stopPlay() {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null;
    el('stepPlay').textContent = '▶ Play'; el('stepPlay').classList.remove('active');
  }
}
el('stepPlay').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  el('stepPlay').textContent = '❚❚ Pause';
  el('stepPlay').classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 4200);
});

/* ── init ───────────────────────────────────────────────────────────────── */
updateRegionButtons();
applyR(2);
goToStep(0);
// @FIGURE_CODE_END

