  g.userData.shaft.position.set(0, sl / 2, 0);
  g.userData.shaft.scale.set(shaftR, sl, shaftR);
  g.userData.head.position.set(0, sl + hl / 2, 0);
  g.userData.head.scale.set(headR, hl, headR);
