/* ── Gaussian surface : orange dash tubes ───────────────────────────────── */
const dashMat = new THREE.MeshBasicMaterial({
  color: ORANGE, transparent: true, opacity: 1, depthTest: false, depthWrite: false
});
const dashGroup = new THREE.Group(); root.add(dashGroup);
const dashPool = [];
const DASH_R = 0.038;
let dashCount = 0;
function getDash(i) {
  while (dashPool.length <= i) {
    const m = new THREE.Mesh(UNIT_CYL, dashMat);
    m.renderOrder = 24; m.visible = false;
    dashGroup.add(m); dashPool.push(m);
  }
  return dashPool[i];
}
const _d0 = new THREE.Vector3();
function emitDash(ax, ay, az, bx, by, bz) {
  _d0.set(bx - ax, by - ay, bz - az);
  const L = _d0.length();
  if (L < 1e-5) return;
  const m = getDash(dashCount++);
  m.position.set((ax + bx) / 2, (ay + by) / 2, (az + bz) / 2);
  m.quaternion.setFromUnitVectors(UP, _d0.clone().normalize());
  m.scale.set(DASH_R, L, DASH_R);
  m.visible = true;
}
function dashPolyline(pts, dashLen, gapLen) {
  const period = dashLen + gapLen;
  let phase = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i], b = pts[i + 1];
    const dx = b.x - a.x, dy = b.y - a.y, dz = b.z - a.z;
    const L = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (L < 1e-6) continue;
    let t = 0;
    while (t < L - 1e-6) {
      const on = phase < dashLen;
      const rem = on ? dashLen - phase : period - phase;
      const step = Math.min(rem, L - t);
      if (on) {
        const u0 = t / L, u1 = (t + step) / L;
        emitDash(a.x + dx * u0, a.y + dy * u0, a.z + dz * u0,
          a.x + dx * u1, a.y + dy * u1, a.z + dz * u1);
      }
      t += step; phase = (phase + step) % period;
    }
  }
}
function ellipsePts(x, r) {
  const p = [];
  for (let i = 0; i <= 64; i++) { const a = i / 64 * Math.PI * 2; p.push(new THREE.Vector3(x, r * Math.cos(a), r * Math.sin(a))); }
  return p;
}
function rebuildGaussian(r) {
  dashCount = 0;
  dashPolyline(ellipsePts(XN - 0.05, r), 0.25, 0.18);
  dashPolyline(ellipsePts(XF - 0.12, r), 0.25, 0.18);
  dashPolyline([new THREE.Vector3(XN - 0.05, r, 0), new THREE.Vector3(XF - 0.12, r, 0)], 0.28, 0.20);
  dashPolyline([new THREE.Vector3(XN - 0.05, -r, 0), new THREE.Vector3(XF - 0.12, -r, 0)], 0.28, 0.20);
  for (let i = dashCount; i < dashPool.length; i++) dashPool[i].visible = false;
}

