function updateLeader(r) {
  const end = new THREE.Vector3(0.5, r + 0.10, 0);
  const pts = [
    TEXT_ANCHOR.clone(),
    new THREE.Vector3(1.80, 4.48, 0),
    new THREE.Vector3(1.20, 4.00, 0),
