  const old = leader.geometry;
  leader.geometry = new THREE.TubeGeometry(curve, 90, 0.035, 6, false);
  old?.dispose?.();
  const p = curve.getPoints(90);
  const dir = p[90].clone().sub(p[84]).normalize();
