/* ── controls & state ───────────────────────────────────────────────────── */
const el = (id) => document.getElementById(id);
const slider = el('gaussianRadius');
const rVal = el('rVal');
const readout = el('readout');
const chkSigns = el('chkSigns'), chkField = el('chkField'), chkShell = el('chkShell');

const REGIONS = {
  inside: { min: 0.3, max: 0.95, btn: 'regInside' },
  gap: { min: 1.0, max: 3.0, btn: 'regGap' },
  outside: { min: 3.05, max: 3.8, btn: 'regOutside' }
};
let region = 'gap';
let currentR = 2;

function applyR(r) {
  currentR = r;
  rVal.textContent = r.toFixed(2);
  if (Math.abs(parseFloat(slider.value) - r) > 1e-6) slider.value = r;

  rebuildGaussian(r);
  gaussShell.scale.set(1, r, r);
  updateLeader(r);

  setArrow(arrRr, farOrigin, dirRr, r, 0.032, 0.26, 0.10);
  const lr = Math.max(0.6, r * 0.62);
  labRr.pos.set(farOrigin.x * S, dirRr.y * lr * S, dirRr.z * lr * S);

  const inGap = region === 'gap';
  const len = Math.max(0.3, Math.min(1.6, 1.8 / r));
  surfArrows.forEach(a => {
    const ang = a.userData.ang;
    const dir = new THREE.Vector3(0, Math.cos(ang), Math.sin(ang));
    setArrow(a, dir.clone().multiplyScalar(r).setX(0), dir, len,
      0.036, Math.min(0.26, len * 0.45), Math.min(0.1, len * 0.22));
    a.visible = inGap && chkField.checked;
  });
  nearArrows.forEach(a => { a.visible = chkField.checked; });

  dashMat.color.setHex(inGap ? ORANGE : 0x9AA2BA);
  gaussShell.material.color.setHex(inGap ? ORANGE : 0x9099AE);
  gaussShell.material.opacity = inGap ? 0.08 : 0.05;

  let qTxt, eTxt;
  if (region === 'inside') {
    qTxt = 'Q<sub>enc</sub> = 0 &nbsp;(surface lies inside the metal)';
    eTxt = '<b>E = 0</b>';
  } else if (region === 'outside') {
    qTxt = 'Q<sub>enc</sub> = +Q − Q = 0';
    eTxt = '<b>E = 0</b> &nbsp;(no field escapes)';
  } else {
    qTxt = 'Q<sub>enc</sub> = +Q = λL &nbsp;(fixed)';
    eTxt = 'E = λ/(2πε₀r) ∝ 1/r = <b>' + (1 / r).toFixed(3) + '</b> (arb.)';
  }
  readout.innerHTML =
    'r = <b>' + r.toFixed(2) + '</b> &nbsp; (R₁ = 1, R₂ = 3)<br>' +
    qTxt + '<br>' + eTxt +
    '<br><span style="color:#555">C = 2πε₀L / ln(R₂/R₁)</span>';
