  });
}
function setRegion(k, value) {
  region = k;
  const R = REGIONS[k];
  slider.min = R.min; slider.max = R.max;
  let v = (value != null) ? value : currentR;
  v = Math.min(R.max, Math.max(R.min, v));
  updateRegionButtons();
  return v;
}

slider.addEventListener('input', () => { cancelTween(); applyR(parseFloat(slider.value)); });
